def solve_game(N):
    """Simulates the card game for N cards using a greedy optimal strategy.
    Grogg (Player 1, Minimizer) tries to keep sums balanced.
    Winnie (Player 2, Maximizer) tries to maximize the difference.
    Cards are taken in descending order N, N-1, ..., 1.
    """
    cards = list(range(N, 0, -1))
    pile1_sum = 0
    pile2_sum = 0

    for i, card in enumerate(cards):
        is_grogg_turn = (i % 2 == 0) # Grogg goes first (i=0, 2, ...)

        if is_grogg_turn:
            # Grogg (Minimizer): Assign to the larger pile to reduce difference
            if pile1_sum >= pile2_sum:
                pile1_sum += card
            else:
                pile2_sum += card
        else:
            # Winnie (Maximizer): Assign to the smaller pile to increase difference
            if pile1_sum <= pile2_sum:
                pile1_sum += card
            else:
                pile2_sum += card

    return abs(pile1_sum - pile2_sum)

# Verification of small cases
